using BragaEventos.Models; namespace BragaEventos.Views; public partial class ResumoPage:ContentPage {public ResumoPage(Evento evento){InitializeComponent();BindingContext=evento;}protected override async void OnAppearing(){base.OnAppearing();Opacity=0;TranslationY=18;await Task.WhenAll(this.FadeTo(1,350),this.TranslateTo(0,0,400,Easing.CubicOut));}async void Voltar(object sender,EventArgs e)=>await Navigation.PopAsync();}